def split_sections(markdown):
    sections, current = [], {"path": [], "lines": []}
    for line in markdown.splitlines():
        if line.startswith("## "):
            if current["lines"]:
                sections.append(current)
            current = {"path": [line[3:].strip()], "lines": [line]}
        else:
            current["lines"].append(line)
    if current["lines"]:
        sections.append(current)
    return sections

def window_words(text, size=90, overlap=18):
    words = text.split()
    step = max(1, size - overlap)
    for start in range(0, len(words), step):
        yield " ".join(words[start:start + size])

policy = """## Refunds
Standard plans can be refunded within 30 days.
Enterprise contracts require finance approval after 30 days.
Refunds are denied when usage violates the acceptable-use policy.
"""

for section in split_sections(policy):
    for i, chunk in enumerate(window_words("
".join(section["lines"]))):
        print({"heading": section["path"], "chunk": i, "text": chunk})
